const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-118.5267, 34.0485]); // Pacific Palisades
  const roi = point.buffer(3000); // 3km buffer for north/west area

  const date1Start = '2025-01-06';
  const date1End = '2025-01-07';
  const date2Start = '2025-01-14';
  const date2End = '2025-01-15';

  // Function to get Sentinel-2 images with cloud masking
  function getS2Collection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
      .map(function(img) {
        // Cloud masking using QA60 band
        var qa = img.select('QA60');
        var cloudBitMask = 1 << 10;
        var cirrusBitMask = 1 << 11;
        var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                  .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return img.updateMask(mask).divide(10000);
      });
  }

  // 2. Data Acquisition
  const col1 = getS2Collection(date1Start, date1End);
  const col2 = getS2Collection(date2Start, date2End);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Jan 6 Images: ${size1}`);
  console.log(`Jan 14 Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate NBR (Normalized Burn Ratio)
  // NBR = (NIR - SWIR) / (NIR + SWIR)
  function addNBR(image) {
    const nbr = image.normalizedDifference(['B8', 'B12']).rename('NBR');
    return image.addBands(nbr);
  }

  const img1 = addNBR(col1.median());
  const img2 = addNBR(col2.median());

  // 4. Calculate burned area (NBR < 0.1 indicates burned area)
  function calcBurnedArea(img) {
    const burned = img.select('NBR').lt(0.1);
    return burned;
  }

  const burned1 = calcBurnedArea(img1);
  const burned2 = calcBurnedArea(img2);

  // Get pixel counts
  const params = {
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  };

  const count1 = burned1.reduceRegion(params).get('NBR').getInfo();
  const count2 = burned2.reduceRegion(params).get('NBR').getInfo();

  console.log(`Burned Jan 6: ${count1} pixels`);
  console.log(`Burned Jan 14: ${count2} pixels`);

  // Check for no valid pixels
  if (count1 === 0 && count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  if (count1 === null || count2 === null || 
      typeof count1 !== 'number' || typeof count2 !== 'number') {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if burned area increased (allowing 10% tolerance for noise)
  const increasePercent = ((count2 - count1) / count1) * 100;
  console.log(`Change: ${increasePercent.toFixed(1)}%`);

  if (count2 > count1 * 1.1) { // >10% increase
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
